{
  "items": [
    {
      "name": "IsIntegral",
      "module_name": "Mathlib.RingTheory.IntegralClosure.IsIntegral.Defs",
      "kind": "definition",
      "type": "(R : Type u_1) → {A : Type u_3} → [inst : CommRing R] → [inst_1 : Ring A] → [Algebra R A] → A → Prop"
    },
    {
      "name": "IsIntegral.of_aeval_monic",
      "module_name": "Mathlib.RingTheory.IntegralClosure.IsIntegral.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_2} [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : Algebra R A] {x : A}\n  {p : Polynomial R}, p.Monic → p.natDegree ≠ 0 → IsIntegral R ((Polynomial.aeval x) p) → IsIntegral R x"
    },
    {
      "name": "minpoly.two_le_natDegree_iff",
      "module_name": "Mathlib.FieldTheory.Minpoly.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} {B : Type u_2} [inst : CommRing A] [inst_1 : Ring B] [inst_2 : Algebra A B] {x : B} [Nontrivial B],\n  IsIntegral A x → (2 ≤ (minpoly A x).natDegree ↔ x ∉ (algebraMap A B).range)"
    },
    {
      "name": "NormedAlgebra.Real.exists_isMonicOfDegree_two_and_aeval_eq_zero",
      "module_name": "Mathlib.Analysis.Normed.Algebra.GelfandMazur",
      "kind": "theorem",
      "type": "∀ {F : Type u_1} [inst : NormedRing F] [inst_1 : NormedAlgebra ℝ F] [NormOneClass F] [NormMulClass F] (x : F),\n  ∃ p, p.IsMonicOfDegree 2 ∧ (Polynomial.aeval x) p = 0"
    },
    {
      "name": "isInteger_of_is_root_of_monic",
      "module_name": "Mathlib.RingTheory.Polynomial.RationalRoot",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} {K : Type u_2} [inst : CommRing A] [IsDomain A] [UniqueFactorizationMonoid A] [inst_3 : Field K]\n  [inst_4 : Algebra A K] [IsFractionRing A K] {p : Polynomial A},\n  p.Monic → ∀ {r : K}, (Polynomial.aeval r) p = 0 → IsLocalization.IsInteger A r"
    },
    {
      "name": "IsIntegral.of_aeval_monic_of_isIntegral_coeff",
      "module_name": "Mathlib.RingTheory.Polynomial.IsIntegral",
      "kind": "theorem",
      "type": "∀ {R : Type u_4} {A : Type u_5} [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : Algebra R A] {x : A}\n  {p : Polynomial A},\n  p.Monic →\n    p.natDegree ≠ 0 → IsIntegral R (Polynomial.eval x p) → (∀ (i : ℕ), IsIntegral R (p.coeff i)) → IsIntegral R x"
    },
    {
      "name": "minpoly",
      "module_name": "Mathlib.FieldTheory.Minpoly.Basic",
      "kind": "definition",
      "type": "(A : Type u_1) → {B : Type u_2} → [inst : CommRing A] → [inst_1 : Ring B] → [Algebra A B] → B → Polynomial A"
    },
    {
      "name": "AdjoinRoot.isIntegral_root'",
      "module_name": "Mathlib.RingTheory.AdjoinRoot",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {g : Polynomial R}, g.Monic → IsIntegral R (AdjoinRoot.root g)"
    }
  ]
}
